<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {plans} from '../stores/plans';import {lots} from '../stores/lots';import {runs} from '../stores/runs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {pct} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),selected=ref<string[]>([]),target=ref(.95),budget=ref(480),seed=ref(20261112);const {error,busy,act}=useTask();const router=useRouter();onMounted(async()=>{await Promise.all([plans.load(),lots.load()]);selected.value=lots.items.value.filter(r=>r.id.startsWith('demo-')).map(r=>r.id)});function submit(){act(async()=>{await plans.create({name:name.value,lot_ids:selected.value,target_detection:target.value,budget:budget.value,seed:seed.value});name.value=''})}function execute(id:string){act(async()=>{const r=await runs.create({plan_id:id});await router.push('/allocation?run='+r.id)})}</script><template><PageHeading index="02 / 抽样计划" title="先定检出目标，再看预算够不够。" note="目标按风险层判断。D为层内各批次ceil(N×预估差错率)之和；不是每批单独达标保证。"/><Notice :message="error"/><div class="two-col"><section><article v-for="r in plans.items.value" :key="r.id" class="plan-row"><p class="eyebrow">SAMPLING PLAN</p><h2>{{r.name}}</h2><dl><div><dt>层级目标</dt><dd>{{pct(r.target_detection)}}</dd></div><div><dt>总预算</dt><dd>{{r.budget}}</dd></div><div><dt>选择批次</dt><dd>{{r.lot_ids.length}}</dd></div></dl><p class="seed-note">seed {{r.seed}} · 无放回抽样</p><button v-if="canWrite()" :disabled="busy" @click="execute(r.id)">计算预算与样本 →</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>建立抽样计划</h2><label>计划名称<input v-model="name" required minlength="2"></label><fieldset><legend>纳入批次</legend><label v-for="r in lots.items.value" :key="r.id" class="checkbox-label"><input type="checkbox" :value="r.id" v-model="selected">{{r.name}} <small>{{r.size}}份</small></label></fieldset><div class="form-pair"><label>目标检出率<input type="number" v-model.number="target" min="0" max="1" step=".01"></label><label>总复核预算<input type="number" v-model.number="budget" min="1" max="5000"></label></div><label>随机种子<input type="number" v-model.number="seed" min="0" max="2147483647"></label><button :disabled="busy||!selected.length">保存计划口径</button></form></div></template>
